// Block (composition) — a responsive semantic list of key/value details.
// Grid owns columns; Stack owns spacing within each description pair.
import type { ReactNode, Ref } from "react";
import { Grid } from "../layouts/Grid";
import type { Responsive } from "../layouts/responsive";
import { Stack } from "../layouts/Stack";
import "./DescriptionList.css";

export interface DescriptionListProps {
  /**
   * Term and description pairs to display. A term is usually words; a node is for a term that must
   * hold its own shape, such as a long name kept to one line (`<Text variant="label" maxLines={1}>`).
   */
  items: {
    term: ReactNode;
    description: ReactNode;
  }[];
  /** Responsive number of equal-width detail columns. */
  columns?: Responsive<number>;
  /**
   * How each pair is laid out: `vertical` puts the term above its value (a summary read top to
   * bottom), `horizontal` puts the term at the start and its value at the end of one line (a
   * property list read down its terms, as a tool's inspector is).
   *
   * @default "vertical"
   */
  orientation?: "vertical" | "horizontal";
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function DescriptionList({
  items,
  columns = { small: 1, medium: 2 },
  orientation = "vertical",
  className,
  ref,
}: DescriptionListProps) {
  const horizontal = orientation === "horizontal";
  const pairs = items.map((item, index) => {
    /* The term and a plain-text value share their start with any box a value renders (a Badge), so
       they take the text inset; a node value is the consumer's to place (component-contract.md §6
       rule 8). */
    const term = <dt className="sd-descriptionlist__term sd-type-label-medium">{item.term}</dt>;
    const value =
      typeof item.description === "string" || typeof item.description === "number" ? (
        <dd className="sd-descriptionlist__value sd-type-body-medium">{item.description}</dd>
      ) : (
        <dd className="sd-descriptionlist__value sd-type-body-medium">{item.description}</dd>
      );
    return horizontal ? (
      <Stack as="div" key={index} direction="row" justify="between" align="baseline" gap="medium" className="sd-descriptionlist__item">
        {term}
        {value}
      </Stack>
    ) : (
      <Stack as="div" key={index} gap="2x-small" className="sd-descriptionlist__item">
        {term}
        {value}
      </Stack>
    );
  });
  const cls = className ? `sd-descriptionlist ${className}` : "sd-descriptionlist";
  /* A line per pair reads as one list, so its lines sit closer than stacked pairs do. */
  return horizontal ? (
    <Grid as="dl" ref={ref} columns={columns} gap="small" className={cls}>
      {pairs}
    </Grid>
  ) : (
    <Grid as="dl" ref={ref} columns={columns} gap="medium" className={cls}>
      {pairs}
    </Grid>
  );
}

/* DescriptionList.css — .sd-descriptionlist (Block)
   Arrangement only: Grid owns columns and Stack owns pair spacing. */
.sd-descriptionlist {
  width: 100%;
  margin: 0;
}

.sd-descriptionlist__value {
  margin: 0;
}
